query EventSeriesListQuery($after: String, $filters: ActivitySeriesFilter, $first: Int, $sortBy: ActivitySeriesSortField, $sortOrder: SortOrder) {
  activitySeriesConnection(
    after: $after
    first: $first
    filters: $filters
    sortBy: $sortBy
    sortOrder: $sortOrder
  ) {
    edges {
      cursor
      node {
        ...EventSeriesFragment
        cluster {
          id
          name
          __typename
        }
        activityConnection(first: 1) {
          nodes {
            id
            message
            __typename
          }
          __typename
        }
        __typename
      }
      __typename
    }
    pageInfo {
      endCursor
      hasNextPage
      hasPreviousPage
      __typename
    }
    __typename
  }
}

fragment EventSeriesFragment on ActivitySeries {
  id
  fid
  activitySeriesId
  lastUpdated
  lastActivityType
  lastActivityStatus
  objectId
  objectName
  objectType
  severity
  progress
  isCancelable
  isPolarisEventSeries
  location
  __typename
}

query ObjectDetailQuery($snappableFid: String!, $snapshotFid: String!) {
                policyObj(snappableFid: $snappableFid, snapshotFid: $snapshotFid) {
                    id
                    rootFileResult {
                        hits {
                            totalHits
                    }
                    analyzerGroupResults {
                        analyzerGroup {
                            name
                        }
                        analyzerResults {
                            hits {
                                totalHits
                            }
                            analyzer {
                                name
                            }
                        }
                            hits {
                            totalHits
                        }
                    }
                    filesWithHits {
                        totalHits
                    }
                    openAccessFiles {
                        totalHits
                    }
                    openAccessFolders {
                        totalHits
                    }
                    openAccessFilesWithHits {
                        totalHits
                    }
                    staleFiles {
                        totalHits
                    }
                    staleFilesWithHits {
                        totalHits
                    }
                    openAccessStaleFiles {
                        totalHits
                    }
                    }
                }
            }

query AnomalyResultQuery($clusterUuid: UUID!, $snapshotId: String!) {
  anomalyResultOpt(clusterUuid: $clusterUuid, snapshotId: $snapshotId) {
    id
    anomalyType
   snapshotFid
    resolutionStatus 
   managedId
    anomalyProbability
    location
    isAnomaly
    objectType
    severity
    detectionTime
    snapshotDate
    encryption
    anomalyInfo {
      strainAnalysisInfo {
        strainId
        totalAffectedFiles
        totalRansomwareNotes
        sampleAffectedFilesInfo {
          filePath
          lastModified
          fileSizeBytes
          __typename
        }
        sampleRansomwareNoteFilesInfo {
          filePath
          lastModified
          fileSizeBytes
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
}

query SnappableInvestigationsQuery($id: UUID!) {
  snapshot(snapshotFid: $id) {
    date
    cluster {
      id
      name
      version
      status
      __typename
    }
    cdmId
    snappableNew {
      name
      id
      cdmId
      objectType
      ... on VsphereVm {
        authorizedOperations
        __typename
      }
      ... on VolumeGroup {
        logicalPath {
          fid
          name
          __typename
        }
        __typename
      }
      ... on NutanixVm {
        authorizedOperations
        __typename
      }
      ... on HyperVVirtualMachine {
        authorizedOperations
        __typename
      }
      ... on LinuxFileset {
        host {
          id
          name
          __typename
        }
        failoverClusterApp {
          id
          name
          __typename
        }
        __typename
      }
      ... on WindowsFileset {
        host {
          id
          name
          __typename
        }
        failoverClusterApp {
          id
          name
          __typename
        }
        __typename
      }
      ... on ShareFileset {
        host {
          id
          name
          __typename
        }
        share {
          id
          name
          __typename
        }
        shareType
        __typename
      }
      ... on NasFileset {
        nasShare {
          id
          name
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
}

