      id
      name
      __typename
    }
    protectionDate
    reportWorkload {
      id
      logicalBytes
      physicalBytes
      archiveStorage
      __typename
    }
    cluster {
      id
      name
      status
      version
      lastConnectionTime
      defaultAddress
      ...ClusterNodeConnectionFragment
      ...ClusterStateFragment
      ...ClusterGlobalManagerFragment
      __typename
    }
    primaryClusterLocation {
      id
      name
      __typename
    }
    arrayIntegrationEnabled
    snapshotConsistencyMandate
    agentStatus {
      agentStatus
      __typename
    }
    preBackupScript {
      scriptPath
      failureHandling
      timeoutMs
      __typename
    }
    postBackupScript {
      scriptPath
      failureHandling
      timeoutMs
      __typename
    }
    postSnapScript {
      scriptPath
      failureHandling
      timeoutMs
      __typename
    }
    logicalPath {
      fid
      objectType
      name
      __typename
    }
    physicalPath {
      fid
      objectType
      name
      __typename
    }
    vsphereTagPath {
      fid
      objectType
      name
      __typename
    }
    oldestSnapshot {
      id
      date
      isIndexed
      __typename
    }
    totalSnapshots: snapshotConnection {
      count
      __typename
    }
    replicatedObjects {
      id
      primaryClusterLocation {
        id
        name
        __typename
      }
      cluster {
        name
        id
        __typename
      }
      __typename
    }
